        }
        std.mem.swap(std.ArrayListUnmanaged(_RegThread), &cur, &nxt);
        for (cur.items) |t| { if (re.nodes[t.state].kind == .match) { last = t.saves; if (re.flags.lazy_match) return last; break; } }
